import type { LanguageCode } from "./catalogue"

/**
 * Complement propre au client web.
 *
 * Le catalogue principal est porte du mobile et ne doit pas etre edite a la main,
 * pour qu'une resynchronisation reste mecanique. Les mentions que le web affiche
 * et que le mobile n'a pas — etats d'appel detailles, indicateur de temps reel,
 * intitules des reglages — vivent donc ici.
 *
 * Meme convention que le catalogue principal : neuf langues, repli sur le
 * francais puis sur la cle. Ces chaines etant affichees a l'utilisateur, elles
 * portent leur typographie d'origine — accents, alphabets, apostrophes.
 */
