  // elles-memes reutilisent des cles existantes : `send_message`, `audio_call`
  // et `video_call`. Ne vivent ici que les libelles que le menu est seul a
  // porter — son intitule accessible et le cas « ecrire a soi-meme ».
  "mc_actions",
  "mc_actions_for",
  "mc_write_to",
  "mc_note_to_self",
  // Conversation avec soi-meme — le « Moi » de WhatsApp. Le NOM de cette
  // conversation reutilise `l2_me`, deja traduit partout : ne vivent ici que
  // les deux mentions qui lui sont propres.
  "self_chat_hint",
  "self_is_not_a_contact",
  // Fiche de contact recue ou envoyee dans une discussion
  // (`components/fiche-contact.tsx`). Ses trois actions portent des libelles
  // COURTS — la fiche tient dans une bulle — la ou le reste du depot n'a que
  // des formes longues (`add_contact` = « Ajouter un contact »). Le cas
  // « ecrire a soi-meme » reutilise `mc_note_to_self`, et les retours d'ajout
  // reutilisent `contact_saved`, `contact_exists` et `add_failed`.
  "fc_contact",
  "fc_on_alanya",
  "fc_outside_alanya",
  "fc_its_you",
  "fc_add",
  "fc_call",
  "fc_message",
  "fc_in_contacts",
  // Fenetre d'envoi d'une fiche de contact
  // (`chats/[chatId]/partager-contact.tsx`). L'entree du menu d'envoi, le titre
  // de la fenetre, et les trois mentions du pied. Les deux voies reutilisent
  // `clist_mode_contacts` / `clist_mode_dial`, la recherche `search_contact`,
  // et la validation `send` / `cancel`.
  "pc_menu_entry",
  "pc_title",
  "pc_count",
  "pc_none",
  "pc_full",
  "pc_too_heavy",
  "pc_load_failed",
  // APERCU d'une fiche de contact dans la liste des discussions
  // (`chats/chats.tsx`). Le contenu d'un message CONTACT est du JSON : sans ces
  // deux cles, la ligne sous le nom de la conversation montrait la charge brute
  // — {"v":1,"contacts":[...]} — a l'expediteur comme au destinataire.
  //
  // Deux formes plutot qu'une seule a accorder : un message porte jusqu'a dix
  // fiches, et « +{count} » evite d'avoir une cle par regle de pluriel dans
  // neuf langues. Quand la charge est illisible, l'appelant retombe sur
  // `f2_contact`, deja traduit partout.
  "l2_contact_shared",
  "l2_contacts_shared",
